export const meta = {
  name: 'cmake-author',
  description: 'CMake research program phase 7: opus drafters write each depth file from the consolidations, pipelined into one index drafter per rule; the two skills and the bazel-quality pointer patch draft alongside',
  phases: [
    { title: 'Depth', detail: 'one opus drafter per depth file', model: 'opus' },
    { title: 'Index', detail: 'one opus drafter per rule index, after its depth files exist', model: 'opus' },
    { title: 'Standalone', detail: 'skills and the proposed bazel-quality patch', model: 'opus' },
  ],
}

// Generated by mkplan.py. PLAN = { rules: [{ rule, core_family, glob_list, index_sources, depth: [{ file, family, sources, task_hint }] }], standalone: [{ kind, path, sources, brief }] }
const PLAN = __PLAN__

const ROOT = '/home/mherwig/dev/grimoire-lore/.agents/worktrees/java'
const RESEARCH = ROOT + '/.agents/research'
const DATE = PLAN.date
const NOTES_ANCHOR = 'Authoring notes (binding on the drafters)'
const MEASURE = '/home/mherwig/.cache/cmake-measure-scratch'

const CONTEXT = `PROJECT CONTEXT (context for you, not content to reproduce):
- You are a drafter in phase 7 (Author) of the research-lang program for CMake and C++ package management (Conan 2, vcpkg, CPM, FetchContent, Hunter, dependency providers, CPS) and their interoperability including the CMake side of the Bazel seam. Run from ${ROOT} (a git worktree; treat it as the repository root; never cd to /home/mherwig/dev/grimoire-lore). The artifacts you write are published through the lore catalog and loaded by coding agents without a human in the loop. Merging to main publishes; you write files, you never commit.
- BINDING INPUTS, read in this order before writing a line: (1) ${ROOT}/.claude/skills/research-lang/references/rule-distillation.md in full; (2) ${RESEARCH}/cmake-topic-map.md section "## ${NOTES_ANCHOR}" in full, plus every "Cross-consolidation contradictions" list in the "Wave N landed" sections — these are decisions already taken; you apply them, you do not re-take them; (3) the house exemplars ${ROOT}/rules/gradle-build.md (a build-system index), ${ROOT}/rules/gradle-build/dependencies.md (a depth file), ${ROOT}/rules/typescript-packaging.md (a manifest rule) and ${ROOT}/skills/jvm-dependency-triage/SKILL.md (a triage skill) — match their structure, register and density, not their content; (4) the consolidation(s) named in your brief, in full, including their Revision logs and the verification ledgers under the matching cmake-<group>/ directory (a CORRECTED ledger row overrides the consolidation text it corrected).
- The checker every file must pass: python3 ${ROOT}/.claude/skills/research-lang/scripts/check-artifacts.py <path> (for an index, pass the rule file; it checks the support directory with it). Run it on your own output before returning and fix every finding.
- VERIFICATION COMMAND SHAPE (the checker lints these; write them this way from the start): grep or rg with an explicit directory operand and -r, never a bare shell glob like cmake/*.cmake; --include='*.cmake' with the glob QUOTED, never an unquoted **; one -e per alternative, never \\| inside a pattern, and never an unescaped | inside a table cell (write \\| or restructure; a pipe splits the Markdown row); no <angle-bracket> placeholder inside a quoted pattern (bind it first: NAME=example; grep -rn -e "$NAME" src/); no $(...) operands; pipe file lists into xargs -r; -e A -e B is a UNION, never an assertion that both occur; every table row whose first cell is a rule ID is read as a rule definition, so a skill's duplicate MUST list uses | # | Finding | Rule | with the ID last. State in every verification cell whether empty output is the pass or the finding. Where a verification is a cmake configure, name the binary line it assumes and the gate spelling the notes fix for that line.
- PROVE YOUR MUST VERIFICATIONS: for every MUST row whose verification is a command, plant a two-to-ten-line violating fixture and a compliant one under ${MEASURE}/author-<your file stem>/ (on disk, never /tmp), run the command exactly as written against each, and fix the cell if it cannot go red or cannot stay green. CMake binaries: 'ocx package exec kitware/cmake:<3.31|4.3|4.4> -- cmake' from ${ROOT}; gcc for C; ninja via 'ocx package exec ninja-build/ninja -- ninja'. Delete build trees when done.
- Formatting: this repo runs ruff format --check over markdown, so a fenced python block (conanfile.py) must be ruff-stable; CMake snippets are fenced cmake, manifests json, presets json, profiles ini, shell sh. Every version-specific row names the CMake/Conan/vcpkg version and the date verified (${DATE} unless the consolidation dates it). No em dashes in prose; no semicolons in prose (code and tables excepted). Files over 100 lines carry a Contents line. Depth files never link to other depth files; they cite sibling families by ID and say which file owns them.
- Portability: the artifacts ship to strangers. No fleet paths, no hostnames, no repo@sha citations in the shipped text (those live in the corpus); an exemplar may be named ("abseil keeps ...") only when it is public and the fact is load-bearing. No OCX product names: the fleet module is an anonymised worked example ("a vendored bootstrap module") and never named. A pinned decision is written as a default the adopter overrides once, and marked pinned.
- Budget: an index under 200 lines; a depth file under 300 lines and usually 150 to 250; a SKILL.md under 500 lines with references one level deep. Rules that fail the four selection tests (agent gets it wrong unaided, checkable, changes a diff, no contradiction) are dropped, and the drop is recorded in your receipt with the ID, never silently.
- Use read-only tools everywhere except your own OUTPUT FILE(S) and your fixture directory. Do not edit a consolidation. Do not edit another drafter's file.
`

const DEPTH_SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['path', 'lines', 'rule_ids_shipped', 'rule_ids_dropped', 'checker_clean', 'hoist_to_index', 'musts_exercised'],
  properties: {
    path: { type: 'string' }, lines: { type: 'number' },
    rule_ids_shipped: { type: 'array', items: { type: 'string' } },
    rule_ids_dropped: { type: 'array', items: { type: 'string' }, description: 'ID: reason' },
    checker_clean: { type: 'boolean' },
    musts_exercised: { type: 'array', items: { type: 'string' }, description: 'ID: red on violation? green on clean? (or: reading heuristic, not exercisable)' },
    hoist_to_index: { type: 'array', items: { type: 'string' }, description: 'the 1-3 MUST rows from this file that belong in the index non-negotiables, as "ID: one-line rule"' },
    routing_row: { type: 'string', description: 'the task-worded "Doing..." phrase for the index routing table' },
  },
}

const INDEX_SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['path', 'lines', 'non_negotiables', 'core_rule_ids', 'checker_clean', 'globs'],
  properties: {
    path: { type: 'string' }, lines: { type: 'number' },
    non_negotiables: { type: 'number' }, core_rule_ids: { type: 'array', items: { type: 'string' } },
    checker_clean: { type: 'boolean' }, globs: { type: 'array', items: { type: 'string' } },
  },
}

const STANDALONE_SCHEMA = {
  type: 'object', additionalProperties: false,
  required: ['paths', 'checker_clean', 'notes'],
  properties: { paths: { type: 'array', items: { type: 'string' } }, checker_clean: { type: 'boolean' }, notes: { type: 'array', items: { type: 'string' } } },
}

function depth(rule, d) {
  const out = ROOT + '/rules/' + rule.rule + '/' + d.file
  return agent(`Model rationale: opus — text that becomes an enforced rule; a wrong MUST propagates into every future diff.

${CONTEXT}

YOUR FILE: ${out}  (depth file of the ${rule.rule} rule; ID family ${d.family}; loads when the index routes here for: ${d.task_hint})
SOURCES (read in full): ${d.sources.map(s => RESEARCH + '/' + s).join(', ')}

Write the depth file: frontmatter (title, summary naming the family and what it owns), a one-paragraph scope stating what the family owns and which sibling families own the neighbours (by family name, never by file link), a Contents line, then sections grouped by the check that catches them — each section opens with the gate command(s) stated once and a rule table (| ID | Rule | Rationale | Verification | Severity |) whose rows keep their consolidation IDs verbatim, followed by at most one minimal wrong/right snippet pair per section where the mistake is easier shown than told, then "## What Agents Get Wrong Here" ranked from the consolidation's failure modes. Apply the authoring notes: drop the IDs they name, keep the pinned defaults they set, mark pinned rows, cite the version floors. Where two consolidations conflict, the "Cross-consolidation contradictions" resolution wins. Prove the MUST verifications as the context says. Then run the checker on your file, fix, and return the receipt (hoist_to_index names the 1-3 rows the index must carry as non-negotiables).`,
    { label: 'depth:' + rule.rule + '/' + d.file, phase: 'Depth', model: 'opus', effort: 'high', schema: DEPTH_SCHEMA })
}

function index(rule, depthReceipts) {
  const out = ROOT + '/rules/' + rule.rule + '.md'
  const ok = depthReceipts.filter(Boolean)
  return agent(`Model rationale: opus — the index is the always-loaded surface; every line is paid for in every session.

${CONTEXT}

YOUR FILE: ${out}  (the index of the ${rule.rule} rule)
GLOBS (decided by the authoring notes; copy exactly): ${JSON.stringify(rule.glob_list)}
DEPTH FILES already written by sibling drafters (read each in full): ${ok.map(r => r.path).join(', ')}
Their receipts (hoist candidates and routing phrases): ${JSON.stringify(ok.map(r => ({ path: r.path, hoist: r.hoist_to_index, routing: r.routing_row })))}
CONSOLIDATIONS for the index-owned ${rule.core_family} family and the gate: ${rule.index_sources.map(s => RESEARCH + '/' + s).join(', ')}

Write the index in the shape of ${ROOT}/rules/gradle-build.md: frontmatter (paths = the globs above, summary, keywords, license Apache-2.0, repository https://github.com/ocx-sh/grimoire-lore), a two-line stance, Contents, "## The Gate" (the exact commands, narrowest first, through the project's pinned binary never PATH, with the configure-gate spelling per CMake line as the notes fix it), "## Non-Negotiables" (a numbered table of 12-18 merge-blocking rows, each citing depth IDs; hoist from the receipts, then prune to what must be true in every edit), "## Rules This File Owns" (the ${rule.core_family} rows the notes assign to the index), "## Where the Depth Is" (one task-worded row per depth file, routed by what the reader is doing, plus the sibling-set rows the notes name), "## Severity", "## Siblings". Under 200 lines. Every depth ID cited must exist in a depth file (grep them). Run the checker on the rule file, fix, return the receipt.`,
    { label: 'index:' + rule.rule, phase: 'Index', model: 'opus', effort: 'high', schema: INDEX_SCHEMA })
}

function standalone(item) {
  return agent(`Model rationale: opus — ${item.kind === 'skill' ? 'a procedure agents run unattended; its steps and its refusal conditions are decisions' : 'a patch offered to a published sibling set; it must match that set\'s contract exactly'}.

${CONTEXT}

YOUR OUTPUT: ${item.path}
SOURCES (read in full): ${item.sources.map(s => s.startsWith('/') ? s : RESEARCH + '/' + s).join(', ')}

${item.brief}

Run the checker on your output, fix, return the receipt.`,
    { label: item.kind + ':' + item.path.split('/').slice(-2).join('/'), phase: 'Standalone', model: 'opus', effort: 'high', schema: STANDALONE_SCHEMA })
}

// ---------------------------------------------------------------- Run
const nDepth = PLAN.rules.reduce((n, r) => n + r.depth.length, 0)
log('Authoring: ' + PLAN.rules.length + ' rules, ' + nDepth + ' depth files, ' + PLAN.standalone.length + ' standalone')

const ruleResults = pipeline(
  PLAN.rules,
  rule => parallel(rule.depth.map(d => () => depth(rule, d))),
  (receipts, rule) => {
    const ok = receipts.filter(Boolean)
    if (ok.length < rule.depth.length) log(rule.rule + ': ' + (rule.depth.length - ok.length) + ' depth drafter(s) dropped; index proceeds with ' + ok.length)
    if (!ok.length) return { rule: rule.rule, depth: receipts, index: null }
    return index(rule, ok).then(ix => ({ rule: rule.rule, depth: receipts, index: ix }))
  },
)
const standaloneResults = parallel(PLAN.standalone.map(item => () => standalone(item)))
const [rules, standaloneOut] = await Promise.all([ruleResults, standaloneResults])

const dropped = rules.filter(Boolean).flatMap(r => (r.depth || []).filter(Boolean).flatMap(d => d.rule_ids_dropped || []))
const unclean = [
  ...rules.filter(Boolean).flatMap(r => (r.depth || []).filter(Boolean).filter(d => !d.checker_clean).map(d => d.path)),
  ...rules.filter(Boolean).filter(r => r.index && !r.index.checker_clean).map(r => r.index.path),
  ...standaloneOut.filter(Boolean).filter(s => !s.checker_clean).flatMap(s => s.paths),
]
log('Authoring done: ' + rules.filter(r => r && r.index).length + '/' + PLAN.rules.length + ' indexes · ' + dropped.length + ' IDs dropped · ' + unclean.length + ' files still unclean')
return { rules, standalone: standaloneOut, dropped_ids: dropped, unclean }
